export type Comment=Readonly<{id:number;text:string;likes:number}>;
export type Ticket=Readonly<{id:number;title:string;status:"OPEN"|"CLOSED";assignee:string|null;tags:readonly string[];comments:readonly Comment[];createdAt:string}>;
export function closeTicket(tickets:readonly Ticket[],id:number):Ticket[]{return tickets.map(ticket=>ticket.id===id?{...ticket,status:"CLOSED"}:ticket);}
export function deleteTicket(tickets:readonly Ticket[],id:number):Ticket[]{return tickets.filter(ticket=>ticket.id!==id);}
export function assignTicket(tickets:readonly Ticket[],id:number,login:string):Ticket[]{return tickets.map(ticket=>ticket.id===id?{...ticket,assignee:login}:ticket);}
export function addTag(tickets:readonly Ticket[],id:number,tag:string):Ticket[]{return tickets.map(ticket=>ticket.id===id&&!ticket.tags.includes(tag)?{...ticket,tags:[...ticket.tags,tag]}:ticket);}
export function likeComment(ticket:Ticket,commentId:number):Ticket{return {...ticket,comments:ticket.comments.map(comment=>comment.id===commentId?{...comment,likes:comment.likes+1}:comment)};}
export function nextTicketId(tickets:readonly Ticket[]):number{const max=tickets.reduce((value,ticket)=>Math.max(value,ticket.id),0);if(!Number.isSafeInteger(max)||max>=Number.MAX_SAFE_INTEGER)throw new RangeError("Brak kolejnego bezpiecznego id");return max+1;}
export function prependQuickTicket(tickets:readonly Ticket[],createdAt:string):Ticket[]{const ticket:Ticket={id:nextTicketId(tickets),title:"Nowy ticket",status:"OPEN",assignee:null,tags:[],comments:[],createdAt};return [ticket,...tickets];}
